"""Published Lab 6 checks. Students run but do not edit this file."""

from __future__ import annotations

import contextlib
import importlib
import io
import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

from inventory_tool import report, scan


TOOL_ROOT = Path(__file__).resolve().parents[1]
SCRIPT = TOOL_ROOT / "inventory.py"


def run_cli(*arguments: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [sys.executable, str(SCRIPT), *arguments],
        cwd=TOOL_ROOT,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )


class Lab6PublishedTests(unittest.TestCase):
    def setUp(self) -> None:
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)

    def test_report_table_orders_records_by_name(self) -> None:
        records = [
            {"name": "z.log", "size": 2, "extension": "log"},
            {"name": "a.txt", "size": 1, "extension": "txt"},
        ]
        self.assertEqual(
            report.format_table(records).splitlines()[1:],
            ["a.txt\t1\ttxt", "z.log\t2\tlog"],
        )

    def test_report_json_is_parseable_and_ordered(self) -> None:
        records = [
            {"name": "z.log", "size": 2, "extension": "log"},
            {"name": "a.txt", "size": 1, "extension": "txt"},
        ]
        names = [item["name"] for item in json.loads(report.format_json(records))]
        self.assertEqual(names, ["a.txt", "z.log"])

    def test_normalize_extension_keeps_one_leading_dot(self) -> None:
        self.assertEqual(scan.normalize_extension(" TXT "), ".txt")
        self.assertEqual(scan.normalize_extension(".Log"), ".log")

    def test_valid_config_has_normalized_extensions_and_minimum(self) -> None:
        path = self.root / "config.json"
        path.write_text('{"extensions": ["TXT", ".log"], "min_size": 3}\n', encoding="utf-8")
        self.assertEqual(
            scan.load_config(path),
            {"extensions": [".txt", ".log"], "min_size": 3},
        )

    def test_invalid_json_remains_distinct_from_missing_file(self) -> None:
        invalid = self.root / "invalid.json"
        invalid.write_text("{not json}\n", encoding="utf-8")
        with self.assertRaises(json.JSONDecodeError):
            scan.load_config(invalid)
        with self.assertRaises(FileNotFoundError):
            scan.load_config(self.root / "missing.json")

    def test_scanner_applies_config_values_to_ordinary_files(self) -> None:
        (self.root / "large.txt").write_text("large\n", encoding="utf-8")
        (self.root / "tiny.log").write_text("x\n", encoding="utf-8")
        (self.root / "large.bin").write_text("binary-ish\n", encoding="utf-8")
        (self.root / "directory.txt").mkdir()

        records = scan.scan_directory(
            self.root,
            extensions=[".txt", ".log"],
            min_size=5,
        )

        self.assertEqual([record["name"] for record in records], ["large.txt"])

    def test_cli_keeps_json_separate_from_start_and_completion_logs(self) -> None:
        input_dir = self.root / "input"
        input_dir.mkdir()
        (input_dir / "large.txt").write_text("large\n", encoding="utf-8")
        (input_dir / "tiny.log").write_text("x\n", encoding="utf-8")
        (input_dir / "large.bin").write_text("binary-ish\n", encoding="utf-8")
        config = self.root / "config.json"
        config.write_text(
            '{"extensions": ["TXT", ".log"], "min_size": 5}\n',
            encoding="utf-8",
        )
        log_file = self.root / "inventory.log"

        result = run_cli(
            str(input_dir),
            "--format",
            "json",
            "--config",
            str(config),
            "--log-file",
            str(log_file),
        )

        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(
            [record["name"] for record in json.loads(result.stdout)],
            ["large.txt"],
        )
        log_text = log_file.read_text(encoding="utf-8").lower()
        self.assertIn("start", log_text)
        self.assertIn("complet", log_text)

    def test_cli_logs_a_failed_scan_and_returns_nonzero(self) -> None:
        missing = self.root / "missing-input"
        log_file = self.root / "inventory.log"

        result = run_cli(str(missing), "--log-file", str(log_file))

        self.assertNotEqual(result.returncode, 0)
        self.assertIn("missing-input", result.stderr)
        self.assertIn("fail", log_file.read_text(encoding="utf-8").lower())

    def test_imports_have_no_visible_side_effects(self) -> None:
        stdout = io.StringIO()
        stderr = io.StringIO()
        with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
            for name in ("inventory_tool.report", "inventory_tool.scan", "inventory_tool.cli"):
                sys.modules.pop(name, None)
                importlib.import_module(name)
        self.assertEqual(stdout.getvalue(), "")
        self.assertEqual(stderr.getvalue(), "")


if __name__ == "__main__":
    unittest.main()
